{
  "private": true,
  "scripts": {
    "prepublish": "pnpm build --filter=next-themes",
    "build": "turbo build",
    "start": "turbo start",
    "dev": "turbo dev",
    "test": "turbo test",
    "test:e2e": "pnpm playwright test",
    "lint": "prettier . --write"
  },
  "devDependencies": {
    "@playwright/test": "^1.51.0",
    "@testing-library/react": "^14.2.1",
    "@types/node": "20.5.7",
    "@types/react": "^18.2.65",
    "@types/react-dom": "18.2.7",
    "jsdom": "^24.0.0",
    "prettier": "^3.2.5",
    "tsup": "^8.3.5",
    "turbo": "^1.10.12",
    "typescript": "^5.4.2",
    "vitest": "^1.6.1"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/pacocoursey/next-themes.git"
  },
  "engines": {
    "node": ">=20",
    "pnpm": ">=9"
  }
}

import { PlaywrightTestConfig, devices } from '@playwright/test'

const config: PlaywrightTestConfig = {
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  reporter: process.env.CI ? 'github' : 'list',
  testDir: './test',
  webServer: {
    command: 'pnpm start --filter=example...',
    port: 3000,
    reuseExistingServer: !process.env.CI,
    timeout: 120 * 1000
  },
  use: {
    trace: 'on-first-retry',
    baseURL: 'http://localhost:3000'
  },
  projects: [
    {
      name: 'chromium',
      use: { ...devices['Desktop Chrome'] }
    }
  ]
}

export default config

{
  "name": "styled-jsx-system",
  "version": "0.0.8",
  "repository": "pacocoursey/styled-jsx-system",
  "license": "MIT",
  "main": "./dist/index.js",
  "files": [
    "dist/**"
  ],
  "scripts": {
    "lint": "prettier --write '**/*.jsx'",
    "build": "babel src -d dist"
  },
  "dependencies": {
    "classnames": "^2.2.6",
    "objss": "^1.0.3",
    "styled-jsx": "^3.2.4"
  },
  "devDependencies": {
    "@babel/cli": "^7.7.7",
    "@babel/core": "^7.7.7",
    "@babel/plugin-transform-modules-commonjs": "^7.7.5",
    "@babel/plugin-transform-template-literals": "^7.7.4",
    "@babel/preset-react": "^7.7.4",
    "babel-eslint": "^10.0.3",
    "babel-preset-minify": "^0.5.1",
    "eslint": "^6.6.0",
    "prettier": "^1.19.1"
  },
  "peerDependencies": {
    "react": "^16.12.0",
    "styled-jsx": "^3.2.4",
    "styled-system": "^5.1.2"
  },
  "prettier": {
    "semi": false,
    "singleQuote": true
  },
  "eslintConfig": {
    "parser": "babel-eslint",
    "parserOptions": {
      "ecmaVersion": 8,
      "sourceType": "module",
      "ecmaFeatures": {
        "jsx": true,
        "impliedStrict": true,
        "experimentalObjectRestSpread": true
      },
      "allowImportExportEverywhere": true
    },
    "plugins": [
      "react",
      "import"
    ],
    "extends": [
      "eslint:recommended",
      "plugin:react/recommended"
    ],
    "env": {
      "es6": true,
      "browser": true,
      "node": true
    },
    "rules": {
      "func-names": [
        "error",
        "as-needed"
      ],
      "no-shadow": "error",
      "import/no-mutable-exports": "error",
      "import/no-anonymous-default-export": [
        "error",
        {
          "allowArray": true,
          "allowArrowFunction": true,
          "allowLiteral": true,
          "allowObject": true
        }
      ],
      "no-extra-semi": 0,
      "react/prop-types": 0,
      "react/react-in-jsx-scope": 0,
      "react/no-unescaped-entities": 0,
      "react/jsx-no-target-blank": 0,
      "react/no-string-refs": 0
    }
  },
  "eslintIgnore": [
    "**/node_modules/**/**",
    "**/.next/**/**"
  ]
}

{
  "name": "opus",
  "productName": "Opus",
  "version": "2.1.0",
  "description": "a minimal note-taking app",
  "main": "./src/main.js",
  "scripts": {
    "postinstall": "electron-rebuild",
    "start": "electron .",
    "lint": "eslint --ignore-path .gitignore .",
    "fix": "eslint --ignore-path .gitignore --fix .",
    "clean": "rm ~/.opus && rm ~/Library/Application\\ Support/Opus/Settings",
    "build:mac": "electron-builder -m",
    "build:win": "electron-builder -w",
    "build:linux": "electron-builder -l"
  },
  "repository": "https://github.com/pacocoursey/Opus",
  "author": "Paco Coursey <p@paco.im> (paco.im)",
  "license": "MIT",
  "dependencies": {
    "chokidar": "^2.0.3",
    "electron-better-ipc": "^0.1.1",
    "electron-disable-file-drop": "^1.0.2",
    "electron-settings": "^3.2.0",
    "electron-unhandled": "^1.1.0",
    "flat": "^4.1.0",
    "fs-extra": "^6.0.1",
    "node-abi": "^2.4.4",
    "os-locale": "^3.0.1",
    "quill": "^1.3.6",
    "quill-delta": "^3.6.3",
    "spellchecker": "^3.5.0",
    "turndown": "^5.0.1"
  },
  "devDependencies": {
    "electron": "^3.0.2",
    "electron-builder": "^20.28.4",
    "electron-rebuild": "^1.8.2",
    "eslint": "^4.19.1",
    "eslint-config-airbnb-base": "^12.1.0",
    "eslint-plugin-import": "^2.14.0"
  },
  "bundle": {
    "name": "Opus"
  },
  "build": {
    "appId": "com.pacocoursey.opus",
    "files": [
      "**/*"
    ],
    "mac": {
      "category": "public.app-category.productivity"
    },
    "win": {
      "target": "portable"
    },
    "dmg": {
      "contents": [
        {
          "x": 175,
          "y": 225
        },
        {
          "x": 365,
          "y": 225,
          "type": "link",
          "path": "/Applications"
        }
      ]
    }
  }
}

import { string } from 'rollup-plugin-string'

/**
 * @type {import('vite').UserConfig}
 */
export default {
  plugins: [
    string({
      include: '**/*.txt',
    }),
  ],
  'optimizeDeps.include': ['valtio/vanilla'],
}
